"% model.m : trimnl_03 — Nonlinear climb + coordinated-turn trim
% Solves 3 coupled nonlinear equilibrium equations for [alpha, T, delta_e]
% using a damped Newton iteration with a numerical Jacobian.
% Writes result.json to the current working directory.

clear; clc;

% ---------------- Parameters ----------------
W    = 200000.0;          % weight, lbf
S    = 2100.0;            % wing area, ft^2
h    = 27000.0;           % altitude, ft
V    = 700.0;             % true airspeed, ft/s
gam  = 4.0*(pi/180);      % climb angle, rad
phi  = 25.0*(pi/180);     % bank angle, rad

CL0  = 0.12;  CLa  = 4.9;   CLde = 0.4;     % 1/rad
CD0  = 0.023; kD   = 0.041;
rho0 = 0.0023769;         % slug/ft^3

iT   = 2.0*(pi/180);      % thrust-line incidence vs body axis, rad
zT   = 1.8;               % perpendicular arm of thrust line from CG, ft
Cm0  = 0.018; Cma = -0.28; Cmde = -0.8;    % 1/rad
cbar = 16.0;              % mean aerodynamic chord, ft

% Atmosphere & dynamic pressure
rho  = rho0*exp(-h/23800.0);
qbar = 0.5*rho*V^2;
QS   = qbar*S;

% ---------------- Residual function ----------------
% x = [alpha (rad); T (lbf); delta_e (rad)]
F = @(x) [ QS*(CL0 + CLa*x(1) + CLde*x(3))*cos(phi) ...
           + x(2)*sin(x(1) + iT) - W*cos(gam);                     % vertical
           x(2)*cos(x(1) + iT) ...
           - QS*(CD0 + kD*(CL0 + CLa*x(1) + CLde*x(3))^2) ...
           - W*sin(gam);                                          % flight path
           QS*cbar*(Cm0 + Cma*x(1) + Cmde*x(3)) ...
           + x(2)*sin(iT)*zT ];                                   % pitch about CG

% ---------------- Damped Newton solve (numerical Jacobian) ----------------
guesses = [ 5.0*(pi/180), 28000.0, -0.50*(pi/180);
            2.0*(pi/180), 20000.0, -0.20*(pi/180);
            8.0*(pi/180), 45000.0, -1.00*(pi/180) ];

tol    = 1e-10;
maxit  = 100;
xsol   = [];
for g = 1:size(guesses,1)
    x = guesses(g,:)';
    conv = false;
    for it = 1:maxit
        fx = F(x);
        if norm(fx,inf) < tol
            conv = true; break;
        end
        % numerical Jacobian
        J = zeros(3,3);
        for j = 1:3
            hs = 1e-7*max(abs(x(j)),1.0);
            xp = x; xp(j) = xp(j) + hs;
            J(:,j) = (F(xp) - fx)/hs;
        end
        dx = -J\fx;
        % backtracking line search for robustness
        step = 1.0;
        for ls = 1:40
            xn = x + step*dx;
            if norm(F(xn),inf) < norm(fx,inf) || step < 1e-8
                break;
            end
            step = step/2;
        end
        x = x + step*dx;
        if max(abs(x)) > 1e8, break; end   % divergence guard
    end
    if conv
        xsol = x; break;
    end
end

if isempty(xsol)
    error('Newton iteration failed to converge.');
end

alpha_trim = xsol(1);                 % rad
T_trim     = xsol(2);                 % lbf
de_trim    = xsol(3);                 % rad
n_load     = cos(gam)/cos(phi);       % load factor

% ---------------- Report & write result.json ----------------
fprintf('max residual      = %.3e\n', norm(F(xsol),inf));
fprintf('alpha_trim (deg)  = %.6f\n', alpha_trim*180/pi);
fprintf('thrust (lbf)      = %.3f\n', T_trim);
fprintf('delta_e_trim (deg)= %.6f\n', de_trim*180/pi);
fprintf('load factor       = %.6f\n', n_load);

res = struct( ...
    'alpha_trim_deg',   alpha_trim*180/pi, ...
    'thrust_lbf',       T_trim, ...
    'delta_e_trim_deg', de_trim*180/pi, ...
    'load_factor',      n_load);

fid = fopen('result.json','w');
fprintf(fid, '%s', jsonencode(res));
fclose(fid);"
